import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { sql } from 'drizzle-orm';
import { readMigrationFiles, type MigrationConfig } from 'drizzle-orm/migrator';
import type { Db } from './client.js';

/** SQL migrations generated by drizzle-kit. Resolves the same from `src/` and `dist/`. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../drizzle', import.meta.url));

export interface RunMigrationsOptions {
  /**
   * Apply the migrations up to and including this journal tag (e.g. `0002_files_unique_kind`)
   * and stop, as an upgrade test does to seed an older schema. Defaults to all of them.
   */
  upTo?: string;
}

/** The part of every Drizzle client the migrator uses (drizzle-orm 0.45). */
interface Migratable {
  dialect: {
    migrate(
      migrations: ReturnType<typeof readMigrationFiles>,
      session: unknown,
      config: MigrationConfig,
    ): Promise<void>;
  };
  session: unknown;
}

/** C249.4 (Phase 11, Workflow 11B, platform-ops): the label the migrate lock's key derives from. */
export const MIGRATE_LOCK_LABEL = 'openverify:migrate';

/**
 * C249.4: the session advisory lock's key, `pg_advisory_lock`'s bigint as text (a JavaScript
 * number cannot hold it): the first eight bytes of the label's SHA-256 as a signed integer.
 */
export function migrateLockKey(label: string = MIGRATE_LOCK_LABEL): string {
  return createHash('sha256').update(label).digest().readBigInt64BE(0).toString();
}

/**
 * One dedicated connection (node-postgres' `PoolClient`, a `Client`, or PGlite): a session lock
 * lives and dies with its connection, so it is never taken through a pool.
 */
export interface MigrateLockConnection {
  query(text: string, values?: unknown[]): Promise<unknown>;
}

/** C249.4: another `db:migrate` held the lock past the timeout; run it again (exit 75). */
export class MigrateLockTimeoutError extends Error {
  override name = 'MigrateLockTimeoutError';
  readonly code = 'migrate_lock_timeout';

  constructor(readonly timeoutSeconds: number) {
    super(
      `db:migrate: migrate_lock_timeout: another db:migrate held the lock for ${String(timeoutSeconds)} s; run it again`,
    );
  }
}

/** Postgres' `lock_not_available`: `lock_timeout` ran out while waiting. */
const LOCK_NOT_AVAILABLE = '55P03';

/**
 * C249.4: runs `work` while holding the migrate lock on `connection`, waiting at most
 * `timeoutSeconds` for it (`lock_timeout`, which bounds an advisory lock's wait too, set on the
 * session for the wait and cleared before the work, so no migration statement inherits it). The
 * lock is released after the work, whether it succeeded or not; a connection that dies releases
 * it too.
 * @throws {MigrateLockTimeoutError} when the wait runs out; nothing ran.
 */
export async function withMigrateLock<T>(
  connection: MigrateLockConnection,
  timeoutSeconds: number,
  work: () => Promise<T>,
): Promise<T> {
  const key = migrateLockKey();
  await connection.query("select set_config('lock_timeout', $1, false)", [
    `${String(timeoutSeconds * 1000)}ms`,
  ]);
  let refusal: Error | undefined;
  try {
    await connection.query('select pg_advisory_lock($1::bigint)', [key]);
  } catch (error) {
    refusal =
      (error as { code?: unknown }).code === LOCK_NOT_AVAILABLE
        ? new MigrateLockTimeoutError(timeoutSeconds)
        : (error as Error);
  }
  try {
    await connection.query("select set_config('lock_timeout', '0', false)");
  } catch (error) {
    // A connection that cannot clear the setting cannot be trusted with the work either.
    throw refusal ?? (error as Error);
  }
  if (refusal !== undefined) {
    throw refusal;
  }
  try {
    return await work();
  } finally {
    await connection.query('select pg_advisory_unlock($1::bigint)', [key]);
  }
}

/**
 * How many migrations the database records as applied (Drizzle's `drizzle.__drizzle_migrations`),
 * 0 before the first.
 */
export async function appliedMigrationCount(db: Db): Promise<number> {
  const rowsOf = <Row>(result: unknown): Row[] => (result as { rows: Row[] }).rows;
  const table = rowsOf<{ present: boolean }>(
    await db.execute(
      sql`select to_regclass('drizzle.__drizzle_migrations') is not null as present`,
    ),
  );
  if (table[0]?.present !== true) {
    return 0;
  }
  const count = rowsOf<{ n: number }>(
    await db.execute(sql`select count(*)::int as n from drizzle.__drizzle_migrations`),
  );
  return count[0]?.n ?? 0;
}

/** The journal's tags, in the order `readMigrationFiles` returns the migrations. */
export function migrationTags(): string[] {
  const journal = JSON.parse(
    readFileSync(path.join(MIGRATIONS_FOLDER, 'meta', '_journal.json'), 'utf8'),
  ) as { entries: { tag: string }[] };
  return journal.entries.map((entry) => entry.tag);
}

/**
 * Applies every pending migration on node-postgres or PGlite. Safe to run repeatedly.
 *
 * drizzle-orm ships one migrator per driver, but in 0.45 they are the same function
 * (`readMigrationFiles` then `db.dialect.migrate`); only their parameter types differ.
 * This runs those two steps for any driver, so the unit (PGlite) and integration
 * (node-postgres) suites share it.
 *
 * @throws {Error} when `upTo` names no migration in the journal.
 */
export async function runMigrations(db: Db, options: RunMigrationsOptions = {}): Promise<void> {
  const config: MigrationConfig = { migrationsFolder: MIGRATIONS_FOLDER };
  let migrations = readMigrationFiles(config);
  if (options.upTo !== undefined) {
    const last = migrationTags().indexOf(options.upTo);
    if (last === -1) {
      throw new Error(`runMigrations: no migration is tagged ${options.upTo}`);
    }
    migrations = migrations.slice(0, last + 1);
  }
  const target = db as unknown as Migratable;
  await target.dialect.migrate(migrations, target.session, config);
}
